syntax:
Signal(signal_number, handler_function); 
sigsetjmp(jmp_buf, save_mask); 
longjmp(jmp_buf, return_value);

code_example:
#include <signal.h>
#include <stdio.h>
#include <setjmp.h>
jmp_buf buf;
void handler(int sig) {
  Sio_puts("Caught signal\n");
  longjmp(buf, 1);
}
int main() {
  if (!sigsetjmp(buf, 1)) {
    Signal(SIGINT, handler);
    Sio_puts("starting\n");
    while (1); /* Infinite loop */
  } else {
    Sio_puts("Restored from signal handler\n");
  }
  return 0;
}
